try {
 db();
 // Verify that a committed finish remains visible after the redirect/new connection.
 if($_SERVER['REQUEST_METHOD']!=='POST' && isset($_SESSION['finish_check'])){
  $check=$_SESSION['finish_check'];unset($_SESSION['finish_check']);
  $finished=first('SELECT status FROM work_entries WHERE id=?',[(int)$check['id']]);
  $database=first('PRAGMA database_list');
  $sameFile=(string)($check['db_file']??'')===(string)($database['file']??'');
  if(!$finished || $finished['status']!==($check['status']??'done')){
   $success='';
   if(!$sameFile) $error='После завершения сменился файл SQLite. Проверьте путь к базе командой php tools/diagnose_journal.php.';
   elseif(!$finished) $error='Операция №'.(int)$check['id'].' исчезла после сохранения. Проверьте триггеры SQLite командой php tools/diagnose_journal.php.';
   else $error='Статус операции №'.(int)$check['id'].' изменился после сохранения. Проверьте триггеры SQLite командой php tools/diagnose_journal.php.';
  }
 }
 $requestedPage=(string)($_GET['page']??'work');
 if (in_array($requestedPage,['groups','directory','reports','routes','settings'],true) || ($_GET['action']??'')==='csv') admin_require();
 if(($_GET['action']??'')==='csv')exportCsv();
 if($requestedPage==='reports' && ($_GET['tab']??'')==='groups' && ($_GET['group_csv']??'')==='1'){define('GROUP_EXPORT_ONLY',true);require dirname(__DIR__).'/src/group_reports.php';}
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!hash_equals(token(),(string)($_POST['csrf']??'')))throw new DomainException('Сессия устарела: перезагрузите страницу');
  $requestedAction=(string)($_POST['action']??'');
  if (in_array($requestedAction,['machine','worker','group','group_split','directory_delete','directory_restore','route_create','route_archive','save_settings'],true)) admin_require();
  perform($requestedAction);
  $_SESSION['success']=$_SESSION['success']??'Изменения сохранены';
  $target=in_array($_POST['back']??'',['work','groups','directory','routes','settings'],true)?$_POST['back']:'work';
  header('Location: ?page='.$target,true,303);exit;
 }
}catch(Throwable $e){$error=$e instanceof DomainException?$e->getMessage():'Ошибка базы данных или дублирующийся код: '.$e->getMessage();}
$page=(string)($_GET['page']??'work');
if(!in_array($page,['work','groups','directory','reports','routes','settings'],true))$page='work';
$machines=query('SELECT * FROM machines WHERE active=1 ORDER BY name');
$workers=query('SELECT * FROM workers WHERE active=1 ORDER BY name');
$archivedMachines=$page==='directory'?query('SELECT * FROM machines WHERE active=0 ORDER BY name'):[];
$archivedWorkers=$page==='directory'?query('SELECT * FROM workers WHERE active=0 ORDER BY name'):[];
$groupSearch=trim((string)($_GET['q']??''));
if($page==='groups' && $groupSearch!==''){
 if(preg_match('/^4[0-9]{11}$/D',$groupSearch))$groups=query('SELECT g.* FROM part_groups g JOIN group_steps s ON s.group_id=g.id WHERE s.id=?',[(int)substr($groupSearch,1)]);
 else if(preg_match('/^3[0-9]{11}$/D',$groupSearch))$groups=query('SELECT * FROM part_groups WHERE id=?',[(int)substr($groupSearch,1)]);
 else $groups=query("SELECT * FROM part_groups WHERE instr(lower(name),lower(?))>0 OR CAST(id AS TEXT)=? ORDER BY id DESC LIMIT 1000",[$groupSearch,$groupSearch]);
}else $groups=query('SELECT * FROM part_groups ORDER BY id DESC LIMIT 1000');
$activeWorker=(int)($_GET['active_worker']??0);
$activeMachine=(int)($_GET['active_machine']??0);
$activeWhere=["e.status='active'"];$activeParams=[];
if($activeWorker>0){$activeWhere[]='e.worker_id=?';$activeParams[]=$activeWorker;}
if($activeMachine>0){$activeWhere[]='e.machine_id=?';$activeParams[]=$activeMachine;}
$active=query("SELECT e.*,m.name machine,w.name worker,w.code worker_code,g.name grp FROM work_entries e JOIN machines m ON m.id=e.machine_id JOIN workers w ON w.id=e.worker_id JOIN part_groups g ON g.id=e.group_id WHERE ".implode(' AND ',$activeWhere)." ORDER BY e.id DESC",$activeParams);
$activeTotal=(int)(first("SELECT COUNT(*) total FROM work_entries WHERE status='active'")['total']??0);
$groupReserved=[];foreach(query("SELECT group_id,SUM(quantity) reserved FROM work_entries WHERE status='active' GROUP BY group_id") as $r)$groupReserved[(int)$r['group_id']]=(int)$r['reserved'];
$groupMeta=[];foreach(query("SELECT g.id,p.name parent_name,(SELECT COUNT(*) FROM part_groups c WHERE c.parent_group_id=g.id) children,COALESCE((SELECT SUM(e.quantity) FROM work_entries e WHERE e.group_id=g.id AND e.status='active'),0) reserved FROM part_groups g LEFT JOIN part_groups p ON p.id=g.parent_group_id") as $r)$groupMeta[(int)$r['id']]=$r;
$leafGroupIds=array_fill_keys(array_map('intval',array_column(query("SELECT g.id FROM part_groups g WHERE NOT EXISTS(SELECT 1 FROM part_groups c WHERE c.parent_group_id=g.id)"),'id')),true);
$busyMachines=array_fill_keys(array_column($active,'machine_id'),true);
$entriesTotal=(int)(first('SELECT COUNT(*) total FROM work_entries')['total']??0);
$entries=query("SELECT e.*,COALESCE(m.name,'Станок #' || e.machine_id) machine,COALESCE(w.name,'Работник #' || e.worker_id) worker,COALESCE(g.name,'Группа #' || e.group_id) grp FROM work_entries e LEFT JOIN machines m ON m.id=e.machine_id LEFT JOIN workers w ON w.id=e.worker_id LEFT JOIN part_groups g ON g.id=e.group_id ORDER BY e.id DESC LIMIT 70");
$routes=query('SELECT * FROM routes ORDER BY name');
$routeData=[];foreach($groups as $g)if($g['status']==='open')$routeData[$g['id']]=route_steps((int)$g['id']);
$csrf=token();
