<div class="page-intro"><div><div class="eyebrow">ПРОИЗВОДСТВЕННЫЙ ЖУРНАЛ</div><h1>Рабочее место</h1><p>Сканируйте станок и работника, выберите группу деталей и начните операцию.</p></div><div class="live-pill"><span></span><?=count($active)?> активных операций</div></div><div class="notice scan-notice" id="usb-scan-status" role="status" aria-live="polite">USB-сканер готов: 100000000001 — станок, 200000000001 — работник, 300000000001 — группа. Только цифры (12 знаков); сканер должен отправлять Enter.</div>
<div class="columns work-columns"><section class="card start-card"><div class="card-heading"><div class="heading-icon">＋</div><div><h2>Начать работу</h2><p>Новая производственная операция</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="start"><input type="hidden" name="back" value="work">
<label for="machine">Станок</label><div class="scanner"><select required name="machine_id" id="machine"><option value="">Выберите станок</option><?php foreach($machines as $m):?><option value="<?=$m['id']?>" data-code="<?=h($m['code'])?>" <?=isset($busyMachines[$m['id']])?'disabled':''?>><?=h($m['name'])?> (<?=h($m['code'])?>)<?=isset($busyMachines[$m['id']])?' — В работе':' — Свободен'?></option><?php endforeach;?></select><button type="button" class="scan" data-target="machine">▣ QR</button></div>
<label for="worker">Работник</label><div class="scanner"><select required name="worker_id" id="worker"><option value="">Выберите работника</option><?php foreach($workers as $w):?><option value="<?=$w['id']?>" data-code="<?=h($w['code'])?>"><?=h($w['name'])?> (<?=h($w['code'])?>)</option><?php endforeach;?></select><button type="button" class="scan" data-target="worker">▣ QR</button></div>
<label for="group">Группа деталей</label><div class="scanner"><select required name="group_id" id="group"><option value="">Выберите открытую группу</option><?php foreach($groups as $g):if($g['status']!=='open'||!isset($leafGroupIds[(int)$g['id']]))continue;?><option value="<?=$g['id']?>" data-code="<?=h('3'.str_pad((string)$g['id'],11,'0',STR_PAD_LEFT))?>" data-remaining="<?=max(0,(int)$g['quantity']-(int)$g['completed']-(int)($groupReserved[(int)$g['id']]??0))?>"><?=h($g['name'])?> — <?=$g['completed']?> / <?=$g['quantity']?></option><?php endforeach;?></select><button type="button" class="scan" data-target="group">▣ Код</button></div><p class="sub">Группы нет? <a href="?page=groups">Добавить новую</a></p><div id="route-start" hidden><label>Этап маршрута</label><select name="step_id" id="route-step"></select><p id="route-available"></p></div><label for="batch-quantity">Количество деталей</label><input type="number" name="batch_quantity" id="batch-quantity" min="1" max="1" value="1" required><p class="sub" id="batch-quantity-help">Укажите, сколько деталей берёте в одну операцию.</p><label>Повторная обработка (необязательно, без маршрута)</label><select name="rework_of"><option value="0">Новая деталь</option><?php foreach(query("SELECT e.id,e.part_number,e.group_id,g.name FROM work_entries e JOIN part_groups g ON g.id=e.group_id WHERE e.status='cancelled' AND e.quality_result='rework' AND g.status='open' AND NOT EXISTS(SELECT 1 FROM group_steps gs WHERE gs.group_id=g.id) AND NOT EXISTS(SELECT 1 FROM work_entries r WHERE r.rework_of=e.id) ORDER BY e.id DESC") as $rw):?><option value="<?=$rw['id']?>" data-group="<?=$rw['group_id']?>"><?=h($rw['name'])?> — деталь №<?=$rw['part_number']?></option><?php endforeach;?></select><button class="primary full">▶ Начал работу</button></form></section>
<section class="card active-card"><div class="card-heading active-heading"><div class="heading-icon active-icon">◷</div><div><h2>Сейчас в работе</h2><p>Контроль занятых станков и исполнителей</p></div><span class="chip active-count"><?=count($active)?><?php if($activeWorker||$activeMachine):?> из <?=$activeTotal?><?php endif;?></span></div><form method="get" class="filters active-filters"><input type="hidden" name="page" value="work"><label>Работник<select name="active_worker"><option value="0">Все работники</option><?php foreach(query("SELECT DISTINCT w.id,w.name FROM workers w JOIN work_entries e ON e.worker_id=w.id WHERE e.status='active' ORDER BY w.name") as $aw):?><option value="<?=$aw['id']?>" <?=$activeWorker===(int)$aw['id']?'selected':''?>><?=h($aw['name'])?></option><?php endforeach;?></select></label><label>Станок<select name="active_machine"><option value="0">Все станки</option><?php foreach(query("SELECT DISTINCT m.id,m.name FROM machines m JOIN work_entries e ON e.machine_id=m.id WHERE e.status='active' ORDER BY m.name") as $am):?><option value="<?=$am['id']?>" <?=$activeMachine===(int)$am['id']?'selected':''?>><?=h($am['name'])?></option><?php endforeach;?></select></label><div class="filter-actions"><button class="primary">Показать</button><a class="reset-filter" href="?page=work">Сбросить</a></div></form><?php if(!$active):?><p class="empty">Активных операций пока нет</p><?php endif;?>
<?php foreach($active as $e):$op=first('SELECT o.*,s.name FROM route_operations o JOIN group_steps s ON s.id=o.step_id WHERE o.entry_id=?',[$e['id']]);$splitAlloc=$op?query('SELECT g.name,a.quantity FROM route_operation_allocations a JOIN part_groups g ON g.id=a.group_id WHERE a.entry_id=? ORDER BY a.id',[$e['id']]):query('SELECT g.name,a.quantity FROM work_entry_allocations a JOIN part_groups g ON g.id=a.group_id WHERE a.entry_id=? ORDER BY a.id',[$e['id']]);?><div class="item active-operation"><div class="operation-info"><strong><?=h($e['grp'])?> · <?= $op?h($op['name']).' — '.$op['quantity'].' шт.':($e['quantity']>1?'детали №'.$e['part_number'].'–'.((int)$e['part_number']+(int)$e['quantity']-1).' · '.$e['quantity'].' шт.':($e['quantity']>1?'детали №'.$e['part_number'].'–'.((int)$e['part_number']+(int)$e['quantity']-1).' · '.$e['quantity'].' шт.':'деталь №'.$e['part_number']))?></strong><p><?=h($e['worker'])?> · <?=h($e['machine'])?></p><?php if($splitAlloc):?><small>Распределение: <?=h(implode(' · ',array_map(fn($a)=>$a['name'].': '.$a['quantity'].' шт.',$splitAlloc)))?></small><?php endif;?><small>Начало <?=h($e['started_at'])?> UTC</small></div><button type="button" class="finish" data-batch="<?= (int)($op['quantity']??$e['quantity']??1)?>" data-route-batch="<?= $op?'1':'0'?>" data-finish-entry="<?=(int)$e['id']?>" data-finish-worker-code="<?=h($e['worker_code'])?>" data-finish-worker-name="<?=h($e['worker'])?>">✓ Закончил</button></div><?php endforeach;?></section></div>
<section class="card journal-card"><div class="card-heading"><div class="heading-icon journal-icon">≡</div><div><h2>Журнал последних операций</h2><p>Последние записи производственного процесса</p></div><span class="chip"><?=$entriesTotal?> всего</span></div><?php if(!$entries):?><p class="sub">В базе пока нет операций. Выберите станок, работника и группу, затем нажмите «Начал работу» — запись появится сразу.<?php if(admin_logged_in()):?> Если операции уже были, проверьте файл var/journal.sqlite на сервере: возможно, сайт подключён к новой пустой базе.<?php endif;?></p><?php endif;?><div class="tablewrap"><table><thead><tr><th>ID</th><th>Деталь</th><th>Станок</th><th>Работник</th><th>Начало UTC</th><th>Конец UTC</th><th>Минут</th><th>Статус</th></tr></thead><tbody><?php foreach($entries as $e):?><tr><td><?=$e['id']?></td><td><?=h($e['grp'])?> №<?=$e['part_number']?><?=((int)($e['quantity']??1)>1?'–'.((int)$e['part_number']+(int)$e['quantity']-1).' ('.(int)$e['quantity'].' шт.)':'')?></td><td><?=h($e['machine'])?></td><td><?=h($e['worker'])?></td><td><?=h($e['started_at'])?></td><td><?=h($e['ended_at']??'—')?></td><td><?=$e['duration_seconds']!==null?round($e['duration_seconds']/60,1):'—'?></td><td><span class="chip <?= $e['status']==='done'?'green':'' ?>"><?=h(($e['status']==='cancelled'&&in_array($e['quality_result'],['scrap','rework'],true)?($e['quality_result']==='scrap'?'Брак':'На доработку'):(['done'=>'Готово','active'=>'В работе','cancelled'=>'Отменено'][$e['status']]??$e['status']))??$e['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></section>
