<div class="columns"><section class="card"><h2>Создать группу</h2><form method="post"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="group"><input type="hidden" name="back" value="groups"><label>Название / номер группы</label><input name="name" required maxlength="180" placeholder="Заказ 104-А"><label>Время приёма</label><input type="datetime-local" name="received_at" required value="<?=date('Y-m-d\TH:i')?>"><label>Плановое время изготовления</label><input type="datetime-local" name="planned_at"><label>Количество деталей</label><input type="number" min="1" name="quantity" required><label>Маршрут</label><select name="route_id"><option value="0">Без маршрута</option><?php foreach($routes as $r):if($r['archived'])continue;?><option value="<?=$r['id']?>"><?=h($r['name'])?></option><?php endforeach;?></select><button class="primary full">+ Создать группу</button></form></section><section class="card"><h2>Состояние производства</h2><div class="metrics"><div><b><?=count(array_filter($groups,fn($g)=>$g['status']==='open'))?></b><span>Открытых групп</span></div><div><b><?=count(array_filter($groups,fn($g)=>$g['status']==='closed'))?></b><span>Закрытых групп</span></div></div><p class="sub">Номер детали назначается в начале работы. Счётчик готовых увеличивается только при завершении.</p></section></div>
<section class="card"><h2>Все группы</h2><p class="sub">Группы можно делить повторно на любом уровне. Уже завершённые и находящиеся в работе детали остаются в родительской группе; распределяется свободный остаток.</p><form method="get" class="filters"><input type="hidden" name="page" value="groups"><label>Название, номер или штрихкод<input type="search" name="q" value="<?=h($groupSearch)?>" placeholder="300000000001" autofocus></label><button class="primary">Найти</button><a href="?page=groups">Сбросить</a></form><?php if(!$groups):?><p>Группы не найдены.</p><?php endif;?><?php foreach($groups as $g):$steps=route_steps((int)$g['id']);if(!$steps)continue;?><details><summary><?=h($g['name'])?> — маршрут</summary><table><tr><th>Этап</th><th>Годные</th><th>Доступно</th><th>В работе</th><th>Брак</th><th>Доработок (накоплено)</th></tr><?php foreach($steps as $s):?><tr><td><?=h($s['name'])?> <code><?=h('4'.str_pad((string)$s['id'],11,'0',STR_PAD_LEFT))?></code> <a href="labels.php?step_id=<?=(int)$s['id']?>">Печать контейнера</a></td><td><?=$s['good']?></td><td><?=$s['available']?></td><td><?=$s['reserved']?></td><td><?=$s['scrap']?></td><td><?=$s['rework']?></td></tr><?php endforeach;?></table></details><?php endforeach;?><div class="tablewrap"><table><thead><tr><th>ID</th><th>Название</th><th>Штрихкод</th><th>Приём</th><th>План</th><th>Готово</th><th>Статус</th></tr></thead><tbody><?php foreach($groups as $g):$meta=$groupMeta[(int)$g['id']]??[];$children=(int)($meta['children']??0);$parent=$meta['parent_name']??null;$reserved=(int)($meta['reserved']??0);$free=max(0,(int)$g['quantity']-(int)$g['completed']);?><tr><td><?=$g['id']?></td><td><?= $parent?'<span class="sub">↳ '.h($parent).'</span><br>':''?><a href="?page=reports&amp;tab=groups&amp;group_id=<?=(int)$g['id']?>"><?=h($g['name'])?></a><?php if($children):?> <span class="chip">Контейнер · <?=$children?> подгрупп</span><?php endif;?></td><td><code><?=h('3'.str_pad((string)$g['id'],11,'0',STR_PAD_LEFT))?></code> <a href="labels.php?group_id=<?=(int)$g['id']?>">Печать</a></td><td><?=h($g['received_at'])?></td><td><?=h($g['planned_at']??'—')?></td><td><div class="bar"><i style="width:<?=100*$g['completed']/$g['quantity']?>%"></i></div><?=$g['completed']?> / <?=$g['quantity']?></td><td><span class="chip <?= $g['status']==='closed'?'green':'' ?>"><?= $g['status']==='closed'?'Закрыта':'Открыта' ?></span></td></tr><?php if(!$children&&$g['status']==='open'&&$free>=2):?><tr><td colspan="7"><details class="group-split"><summary>↳ Разделить «<?=h($g['name'])?>» · к распределению <?=$free?> шт. (включая активные операции)</summary><form method="post" class="split-form" onsubmit="return confirm('Распределить <?=$free?> деталей, включая активные операции между новыми подгруппами?');"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="group_split"><input type="hidden" name="back" value="groups"><input type="hidden" name="group_id" value="<?=$g['id']?>"><label>Префикс и количество — по одной подгруппе на строку</label><textarea name="allocations" rows="3" required placeholder="A, 120&#10;B, 180"></textarea><p class="sub">Сумма количеств должна быть ровно <?=$free?> шт. Новые названия: <?=h($g['name'])?>-A, <?=h($g['name'])?>-B и т. д.</p><button class="primary">Разделить группу</button></form></details></td></tr><?php endif;?><?php endforeach;?></tbody></table></div></section>
