$params=[$start,$end];
$stats=first("SELECT COALESCE(SUM(COALESCE(o.quantity,e.quantity)),0) total,COALESCE(SUM(CASE WHEN e.status='done' THEN COALESCE(o.good,e.batch_good) ELSE 0 END),0) done,COALESCE(SUM(CASE WHEN e.status='active' THEN COALESCE(o.quantity,e.quantity) ELSE 0 END),0) active,COALESCE(SUM(CASE WHEN e.status='done' THEN e.duration_seconds ELSE 0 END),0) seconds FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id WHERE e.started_at>=? AND e.started_at<?",$params);
$workerStats=query("SELECT COALESCE(w.name,'Работник #' || e.worker_id) name,COALESCE(SUM(COALESCE(o.quantity,e.quantity)),0) total,COALESCE(SUM(CASE WHEN e.status='done' THEN COALESCE(o.good,e.batch_good) ELSE 0 END),0) done,COALESCE(SUM(CASE WHEN e.status='done' THEN e.duration_seconds ELSE 0 END),0) seconds FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id LEFT JOIN workers w ON e.worker_id=w.id WHERE e.started_at>=? AND e.started_at<? GROUP BY e.worker_id ORDER BY done DESC",$params);
$machineStats=query("SELECT COALESCE(m.name,'Станок #' || e.machine_id) name,COALESCE(SUM(COALESCE(o.quantity,e.quantity)),0) total,COALESCE(SUM(CASE WHEN e.status='done' THEN COALESCE(o.good,e.batch_good) ELSE 0 END),0) done,COALESCE(SUM(CASE WHEN e.status='done' THEN e.duration_seconds ELSE 0 END),0) seconds FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id LEFT JOIN machines m ON e.machine_id=m.id WHERE e.started_at>=? AND e.started_at<? GROUP BY e.machine_id ORDER BY done DESC",$params);
$days=query("SELECT substr(e.started_at,1,10) day,COALESCE(SUM(COALESCE(o.quantity,e.quantity)),0) total,COALESCE(SUM(CASE WHEN e.status='done' THEN COALESCE(o.good,e.batch_good) ELSE 0 END),0) done FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id WHERE e.started_at>=? AND e.started_at<? GROUP BY substr(e.started_at,1,10) ORDER BY day",$params);
?>
<div class="headline"><div><small>ПРОИЗВОДСТВЕННАЯ АНАЛИТИКА</small><h1>Отчёты</h1><p><a class="export" href="?page=reports&amp;tab=groups">Аналитика по группам</a></p><p>Показатели по работникам, станкам и дням; время хранится в UTC.</p></div></div>
<form class="filters" method="get"><input type="hidden" name="page" value="reports"><label>С даты<input type="date" name="from" value="<?=h($from)?>"></label><label>По дату<input type="date" name="to" value="<?=h($to)?>"></label><button class="primary">Применить</button><a class="export" href="?action=csv&amp;from=<?=h($from)?>&amp;to=<?=h($to)?>">↓ Скачать CSV</a></form>
<div class="kpis"><div><span>Деталей в операциях</span><b><?=$stats['total']?></b></div><div><span>Изготовлено</span><b><?=$stats['done']?></b></div><div><span>В работе</span><b><?=$stats['active']?></b></div><div><span>Время работы</span><b><?=round($stats['seconds']/3600,1)?> ч</b></div></div>
<div class="columns"><?php foreach([['По работникам',$workerStats],['По станкам',$machineStats]] as [$title,$data]):?><section class="card"><h2><?=$title?></h2><div class="tablewrap"><table><thead><tr><th>Наименование</th><th>Операций</th><th>Готово</th><th>Часов</th><th>Мин/деталь</th></tr></thead><tbody><?php foreach($data as $r):?><tr><td><?=h($r['name'])?></td><td><?=$r['total']?></td><td><?=$r['done']?></td><td><?=round($r['seconds']/3600,2)?></td><td><?=$r['done']?round($r['seconds']/60/$r['done'],1):'—'?></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?></div>
<section class="card"><h2>Качество производства</h2><?php $qualityRows=query("SELECT e.quality_result,e.quality_reason,COALESCE(w.name,'—') worker,COALESCE(m.name,'—') machine,SUM(COALESCE(o.scrap,e.batch_scrap)) scrap,SUM(COALESCE(o.rework,e.batch_rework)) rework FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id LEFT JOIN workers w ON w.id=e.worker_id LEFT JOIN machines m ON m.id=e.machine_id WHERE e.ended_at>=? AND e.ended_at<? AND COALESCE(o.scrap,e.batch_scrap)+COALESCE(o.rework,e.batch_rework)>0 GROUP BY e.quality_result,e.quality_reason,e.worker_id,e.machine_id",$params);$qualityTotal=first("SELECT COALESCE(SUM(COALESCE(o.good,e.batch_good)+COALESCE(o.scrap,e.batch_scrap)+COALESCE(o.rework,e.batch_rework)),0) n,COALESCE(SUM(COALESCE(o.scrap,e.batch_scrap)),0) scrap FROM work_entries e LEFT JOIN route_operations o ON o.entry_id=e.id WHERE e.ended_at>=? AND e.ended_at<?",$params);?><p>Доля брака среди завершённых обработок: <?=$qualityTotal['n']?round(100*$qualityTotal['scrap']/$qualityTotal['n'],1):0?>%</p><div class="tablewrap"><table><thead><tr><th>Результат</th><th>Причина</th><th>Работник</th><th>Станок</th><th>Количество</th></tr></thead><tbody><?php foreach($qualityRows as $qr):?><tr><td><?=$qr['quality_result']==='scrap'?'Брак':'Доработка'?></td><td><?=h($qr['quality_reason'])?></td><td><?=h($qr['worker'])?></td><td><?=h($qr['machine'])?></td><td><?=((int)$qr['scrap']+(int)$qr['rework'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2>Изготовление по дням</h2><?php if(!$days):?><p class="sub">За выбранный период операций нет.</p><?php endif;?><?php $max=max([1,...array_map(fn($x)=>(int)$x['total'],$days)]);foreach($days as $r):?><div class="day"><span><?=h($r['day'])?></span><div class="bar"><i style="width:<?=100*$r['total']/$max?>%"></i></div><b><?=$r['done']?> / <?=$r['total']?></b></div><?php endforeach;?></section>
<?php endif;?></main>
